const posicao = $('Posição Atual dos Achados').all();
const novos = $('Novos Achados da Semana').all();
const prazo = $('Achados próximos do prazo').all().filter(function(i) {
  return i.json.data_limite_acao !== undefined &&
    i.json.data_limite_acao !== null &&
    i.json.achado_id !== undefined;
});
const valorUnico = $('Valor Total Único').first().json.valor_unico;

const agora = new Date();
const fusoFortaleza = new Date(agora.toLocaleString('en-US', { timeZone: 'America/Fortaleza' }));
const data = fusoFortaleza.toLocaleDateString('pt-BR');

const titulos = {
  1: 'Pagamentos sem aprovacao formal',
  2: 'Atraso no lancamento de despesas',
  3: 'Padrao suspeito de comportamento',
  4: 'Falha combinada - sem aprovacao e atraso',
  7: 'Meios de pagamento de alto risco',
  8: 'Falha no processo fiscal'
};

const totalAbertos = posicao.reduce(function(sum, i) {
  return sum + parseInt(i.json.total_registros || 0);
}, 0);

const totalAlto = posicao.filter(function(i) {
  return i.json.nivel_risco === 'ALTO';
}).reduce(function(sum, i) {
  return sum + parseInt(i.json.total_registros || 0);
}, 0);

let tabelaPosicao = '';
posicao.forEach(function(i) {
  tabelaPosicao += '<tr>';
  tabelaPosicao += '<td>' + i.json.achado_id + '</td>';
  tabelaPosicao += '<td>' + (titulos[i.json.achado_id] || '-') + '</td>';
  tabelaPosicao += '<td>' + i.json.nivel_risco + '</td>';
  tabelaPosicao += '<td>' + i.json.total_registros + '</td>';
  tabelaPosicao += '<td>R$ ' + parseFloat(i.json.valor_total || 0).toFixed(2) + '</td>';
  tabelaPosicao += '<td>' + i.json.status_tratamento + '</td>';
  tabelaPosicao += '</tr>';
});

const novosAgrupados = {};
novos.forEach(function(i) {
  const id = i.json.achado_id;
  if (id === undefined || id === null) return;
  if (!novosAgrupados[id]) {
    novosAgrupados[id] = { count: 0, valor: 0 };
  }
  novosAgrupados[id].count++;
  novosAgrupados[id].valor += parseFloat(i.json.valor || 0);
});

const chavesNovos = Object.keys(novosAgrupados);
let tabelaNovos = '';
if (chavesNovos.length > 0) {
  chavesNovos.forEach(function(id) {
    const d = novosAgrupados[id];
    tabelaNovos += '<tr>';
    tabelaNovos += '<td>' + id + '</td>';
    tabelaNovos += '<td>' + (titulos[id] || '-') + '</td>';
    tabelaNovos += '<td>' + d.count + '</td>';
    tabelaNovos += '<td>R$ ' + d.valor.toFixed(2) + '</td>';
    tabelaNovos += '</tr>';
  });
} else {
  tabelaNovos = '<tr><td colspan="4" style="text-align:center;color:#555;">Nenhum novo achado na semana</td></tr>';
}

let tabelaPrazo = '';
if (prazo.length > 0) {
  prazo.forEach(function(i) {
    tabelaPrazo += '<tr>';
    tabelaPrazo += '<td>' + i.json.achado_id + '</td>';
    tabelaPrazo += '<td>' + (titulos[i.json.achado_id] || '-') + '</td>';
    tabelaPrazo += '<td>' + (i.json.responsavel_acao || 'Nao definido') + '</td>';
    tabelaPrazo += '<td>' + i.json.data_limite_acao + '</td>';
    tabelaPrazo += '<td>' + i.json.status_tratamento + '</td>';
    tabelaPrazo += '</tr>';
  });
} else {
  tabelaPrazo = '<tr><td colspan="5" style="text-align:center;color:#555;">Nenhum achado com prazo nos proximos 7 dias</td></tr>';
}

const valorFormatado = valorUnico ? parseFloat(valorUnico).toFixed(2) : '0.00';

const html = '<h2 style="color:#1a252f;">Relatorio Executivo Semanal de Auditoria</h2>'
  + '<p><strong>Farmagrupo Nordeste SA</strong> | Unidade de Auditoria Interna | ' + data + '</p>'
  + '<hr>'

  + '<h3 style="color:#1a252f;">1. Resumo Executivo</h3>'
  + '<table border="1" cellpadding="8" cellspacing="0" style="border-collapse:collapse;width:100%">'
  + '<tr style="background:#1a252f;color:white;"><td><strong>Indicador</strong></td><td><strong>Valor</strong></td></tr>'
  + '<tr><td>Total de registros em aberto</td><td>' + totalAbertos + '</td></tr>'
  + '<tr><td>Valor total exposto (sem dupla contagem)</td><td>R$ ' + valorFormatado + '</td></tr>'
  + '<tr><td>Registros de risco ALTO</td><td style="color:#c0392b;font-weight:bold;">' + totalAlto + '</td></tr>'
  + '</table>'

  + '<h3 style="color:#1a252f;">2. Posicao Atual dos Achados</h3>'
  + '<table border="1" cellpadding="8" cellspacing="0" style="border-collapse:collapse;width:100%">'
  + '<tr style="background:#1a252f;color:white;">'
  + '<td><strong>#</strong></td>'
  + '<td><strong>Achado</strong></td>'
  + '<td><strong>Risco</strong></td>'
  + '<td><strong>Registros</strong></td>'
  + '<td><strong>Valor Exposto</strong></td>'
  + '<td><strong>Status</strong></td>'
  + '</tr>'
  + tabelaPosicao
  + '</table>'

  + '<h3 style="color:#1a252f;">3. Novos Achados da Semana</h3>'
  + '<table border="1" cellpadding="8" cellspacing="0" style="border-collapse:collapse;width:100%">'
  + '<tr style="background:#1a252f;color:white;">'
  + '<td><strong>#</strong></td>'
  + '<td><strong>Achado</strong></td>'
  + '<td><strong>Registros</strong></td>'
  + '<td><strong>Valor</strong></td>'
  + '</tr>'
  + tabelaNovos
  + '</table>'

  + '<h3 style="color:#1a252f;">4. Achados com Prazo nos Proximos 7 Dias</h3>'
  + '<table border="1" cellpadding="8" cellspacing="0" style="border-collapse:collapse;width:100%">'
  + '<tr style="background:#1a252f;color:white;">'
  + '<td><strong>#</strong></td>'
  + '<td><strong>Achado</strong></td>'
  + '<td><strong>Responsavel</strong></td>'
  + '<td><strong>Prazo</strong></td>'
  + '<td><strong>Status</strong></td>'
  + '</tr>'
  + tabelaPrazo
  + '</table>'

  + '<h3 style="color:#1a252f;">5. Nota Metodologica</h3>'
  + '<p style="font-size:13px;color:#555;">'
  + 'Os Achados 5 e 6 analisam os mesmos registros dos Achados 1 e 2 sob perspectivas diferentes '
  + '(segregacao de funcao e distribuicao sistemica). O Achado 9 e de natureza analitica - '
  + 'concentracao de fornecedores. Os tres nao possuem registros individuais no log_auditoria '
  + 'para evitar dupla contagem. Estao documentados no Relatorio AI-2025-001 e no POA.'
  + '</p>'

  + '<hr>'
  + '<p style="color:gray;font-size:12px;">'
  + 'Gerado automaticamente pelo sistema de Auditoria Continua - Farmagrupo Nordeste SA<br>'
  + 'Referencia IPPF: Norma 15.2 - Confirmando a Implementacao das Recomendacoes<br>'
  + 'Emitido toda segunda-feira as 08:00 | UAI - Unidade de Auditoria Interna'
  + '</p>';

const subject = '[AUDITORIA] Relatorio Executivo Semanal | ' + data;

return [{ json: { html: html, subject: subject } }];
